-- Activate the complete reviewed Buried Sea installation in the same guarded transaction.
SET SESSION check_constraint_checks=1;
DROP TEMPORARY TABLE IF EXISTS `_tbs_activation_guard`;
CREATE TEMPORARY TABLE `_tbs_activation_guard`(ok TINYINT NOT NULL CHECK(ok=1))ENGINE=InnoDB;
START TRANSACTION;
